import os, glob, re, datetime

LOGDIR = "/app/logs"
REF = datetime.date(2025, 8, 12)

def daterange(start, end):
    d = start
    while d <= end:
        yield d
        d += datetime.timedelta(days=1)

SEVS = ["ERROR", "WARNING", "INFO"]
date_sets = {
    "today": {REF},
    "last_7_days": set(daterange(REF - datetime.timedelta(days=6), REF)),
    "last_30_days": set(daterange(REF - datetime.timedelta(days=29), REF)),
    "month_to_date": set(daterange(datetime.date(REF.year, REF.month, 1), REF)),
}
counts = {p: {s: 0 for s in SEVS} for p in date_sets}
total = {s: 0 for s in SEVS}

pat = re.compile(r"\[(ERROR|WARNING|INFO)\]")
for path in glob.glob(os.path.join(LOGDIR, "*.log")):
    fn = os.path.basename(path)
    fdate = datetime.date.fromisoformat(fn[:10])
    with open(path, "r", errors="replace") as fh:
        for line in fh:
            m = pat.search(line)
            if not m:
                continue
            sev = m.group(1)
            total[sev] += 1
            for pname, dset in date_sets.items():
                if fdate in dset:
                    counts[pname][sev] += 1

order = ["today", "last_7_days", "last_30_days", "month_to_date", "total"]
with open("/app/summary.csv", "w") as out:
    out.write("period,severity,count\n")
    for p in order:
        for sev in SEVS:
            val = total[sev] if p == "total" else counts[p][sev]
            out.write(f"{p},{sev},{val}\n")
print("done")
